type node struct {
    key, val   int
    prev, next *node
}

type LRUCache struct {
    cap        int
    m          map[int]*node
    head, tail *node // sentinels: head.next = most recent
}

func (c *LRUCache) remove(n *node) { n.prev.next = n.next; n.next.prev = n.prev }
func (c *LRUCache) pushFront(n *node) {
    n.prev, n.next = c.head, c.head.next
    c.head.next.prev, c.head.next = n, n
}

indeg := make([]int, n)
adj := make([][]int, n)
for _, e := range edges { // e = [dependent, prereq]
    adj[e[1]] = append(adj[e[1]], e[0])
    indeg[e[0]]++
}
q := []int{}
for i := 0; i < n; i++ {
    if indeg[i] == 0 {
        q = append(q, i)
    }
}
seen := 0
for len(q) > 0 {
    u := q[0]
    q = q[1:]
    seen++
    for _, v := range adj[u] {
        indeg[v]--
        if indeg[v] == 0 {
            q = append(q, v)
        }
    }
}
return seen == n // false => a cycle

